<script setup lang="ts">
import { ref,computed,watch } from 'vue'
import { api } from '../../api'
import { usePage,user,perform,busy } from '../../state'
import { positiveDecimal,requestKey } from '../../domain'
import type { Row } from '../../domain'
import PageHeader from '../../components/PageHeader.vue'
import DataTable from '../../components/DataTable.vue'
import LoadState from '../../components/LoadState.vue'
import OperationForm from '../../components/OperationForm.vue'
const tab=ref('reconciliation'),reconciliation=ref<Row>({ok:true,issues:[]}),audit=ref<Row[]>([]),announcements=ref<Row[]>([]),clock=ref<Row>({})
const cashEntries=ref<Row[]>([]),corrections=ref<Row[]>([]),correctionOpen=ref(false),original=ref<Row>({}),difference=ref(''),reason=ref(''),correctionKey=ref(requestKey())
const tabs=computed(()=>user.value?.role==='ADMIN'?[['reconciliation','账务对账'],['cash','资金流水'],['corrections','现金更正'],['audit','操作审计'],['announcements','公告'],['clock','业务时钟']]:[['reconciliation','账务对账'],['cash','资金流水'],['announcements','公告']])
const {loading,error,load}=usePage(async()=>{[reconciliation.value,audit.value,announcements.value,clock.value]=await Promise.all([api.get('/admin/reconciliation'),user.value?.role==='ADMIN'?api.get('/admin/audit'):Promise.resolve([]),api.get('/admin/announcements'),user.value?.role==='ADMIN'?api.get('/admin/clock'):Promise.resolve({})]);if(tab.value==='cash')cashEntries.value=await api.get('/admin/cash-entries');if(tab.value==='corrections'&&user.value?.role==='ADMIN')corrections.value=await api.get('/admin/corrections')})
watch(tab,load)
function correct(row:Row){original.value={...row};difference.value='';reason.value='';correctionKey.value=requestKey();correctionOpen.value=true}
async function saveCorrection(){await perform(async()=>{if(!positiveDecimal(difference.value.replace(/^[+-]/,'')))throw new Error('更正差额应为非零金额，最多两位小数');if(!reason.value.trim())throw new Error('请填写更正理由');return api.post('/admin/corrections',{originalEntryId:original.value.id,availableDelta:difference.value,reason:reason.value.trim(),requestKey:correctionKey.value})},async()=>{correctionOpen.value=false;await load()})}
</script>
<template><PageHeader title="运营与审计" subtitle="检查账务一致性，追溯后台操作，维护平台公告。"><button class="button" @click="load">重新检查</button></PageHeader><LoadState :loading="loading" :error="error" @retry="load"/><div class="tabs"><button v-for="t in tabs" :key="t[0]" :class="{active:tab===t[0]}" @click="tab=t[0]">{{ t[1] }}</button></div><section v-if="tab==='reconciliation'" class="panel"><h2>{{ reconciliation.ok?'账务对账通过':'存在账务异常' }}</h2><p class="notice" :class="{error:!reconciliation.ok}">汇总资产必须等于逐账户资产合计，资金与份额变化必须有可追溯流水。</p><div v-if="!reconciliation.issues?.length" class="empty">本次检查未发现对账异常</div><pre v-for="(issue,index) in reconciliation.issues" :key="index" class="admin-detail">{{ typeof issue==='string'?issue:JSON.stringify(issue,null,2) }}</pre></section><section v-else-if="tab==='cash'" class="panel"><h2>已入账资金流水</h2><p class="notice">流水保留客户、交易账户及业务来源。管理员可关联已入账的收款或提现记录追加现金更正，原记录保持不变。</p><DataTable :rows="cashEntries" :columns="[{key:'id',label:'流水编号'}, {key:'displayName',label:'客户'}, {key:'userId',label:'客户ID'}, {key:'accountNo',label:'交易账户'}, {key:'bankName',label:'银行'}, {key:'sourceType',label:'来源业务'}, {key:'eventType',label:'资金事件'}, {key:'availableDelta',label:'可用变动（元）',kind:'money'}, {key:'frozenDelta',label:'冻结变动（元）',kind:'money'}, {key:'amount',label:'金额（元）',kind:'money'}, {key:'createdAt',label:'时间',kind:'date'}]"><template #actions="{row}"><button v-if="user?.role==='ADMIN' && ['CREDIT','WITHDRAW'].includes(row.eventType)" class="text-button" :disabled="busy>0" @click="correct(row)">追加现金更正</button></template></DataTable></section><section v-else-if="tab==='corrections'" class="panel"><h2>现金更正记录</h2><p class="notice">每笔更正关联原始入账流水，记录管理员与理由。此入口仅处理模拟现金差额，不改变冻结资金、持仓份额或成交历史。</p><DataTable :rows="corrections" :columns="[{key:'id',label:'更正编号'}, {key:'originalEntryId',label:'原始流水'}, {key:'displayName',label:'客户'}, {key:'accountNo',label:'交易账户'}, {key:'availableDelta',label:'更正差额（元）',kind:'money'}, {key:'reason',label:'更正理由'}, {key:'actorId',label:'管理员'}, {key:'createdAt',label:'时间',kind:'date'}]"/></section><section v-else-if="tab==='audit'" class="panel"><DataTable :rows="audit" :columns="[{key:'createdAt',label:'时间',kind:'date'}, {key:'actorId',label:'操作者'}, {key:'action',label:'操作'}, {key:'objectType',label:'对象类型'}, {key:'objectId',label:'对象ID'}, {key:'reason',label:'操作理由'}, {key:'requestId',label:'请求编号'}]"/></section><template v-else-if="tab==='announcements'"><OperationForm title="发布平台公告" :fields="[{key:'title',label:'标题'}, {key:'body',label:'公告正文',type:'textarea'}]" :initial="{title:'',body:''}" :submit="value=>api.post('/admin/announcements',value)" button="发布公告" description="公告采用纯文本展示，不执行HTML或脚本。" @saved="load"/><section class="panel"><div v-for="item in announcements" :key="item.id" class="message-item"><h3>{{ item.title }}</h3><p>{{ item.body }}</p><small class="muted">{{ String(item.createdAt||'').replace('T',' ') }}</small></div><div v-if="!announcements.length" class="empty">暂无公告</div></section></template><template v-else><section class="panel"><h2>当前业务时钟</h2><div class="asset-value" style="font-size:28px">{{ String(clock.dateTime||'—').replace('T',' ') }}</div><p class="muted">Asia/Shanghai · {{ clock.demo?'教学演示配置':'使用真实时间' }}</p><p class="notice">推进演示时钟后，在任务中心执行对应日期的业务。所有时间检查仍由服务端生效。</p></section><OperationForm v-if="clock.demo" title="推进演示时间" :fields="[{key:'dateTime',label:'北京时间',type:'datetime-local'}]" :initial="{dateTime:String(clock.dateTime||'').slice(0,19)}" :submit="value=>api.post('/admin/clock',{dateTime:value.dateTime.length===16?value.dateTime+':00':value.dateTime})" button="更新演示时钟" @saved="load"/><p v-else class="notice">公开环境使用真实业务时钟，无法更改时间。</p></template><el-dialog v-model="correctionOpen" title="追加模拟现金更正" width="650px"><p class="notice">原始记录保留，追加本次更正。差额绝对值不得超过原金额，也不能造成负余额；仅允许已入账的现金收款或提现。</p><DataTable :rows="[original]" :columns="[{key:'displayName',label:'客户'}, {key:'accountNo',label:'交易账户'}, {key:'sourceType',label:'原始来源'}, {key:'amount',label:'原始金额（元）',kind:'money'}]"/><form class="form-grid" style="margin-top:20px" @submit.prevent="saveCorrection"><label><span>原始流水编号</span><input :value="original.id" readonly/></label><label><span>可用现金更正差额（元）</span><input v-model="difference" inputmode="decimal" placeholder="例如 -1.00 或 1.00，非零" required @input="correctionKey=requestKey()"/></label><label class="wide"><span>更正理由</span><textarea v-model="reason" rows="3" required maxlength="500" @input="correctionKey=requestKey()"/></label><div class="wide"><button class="button primary" :disabled="busy>0">追加更正并保留原流水</button></div></form></el-dialog></template>
